## Code Example
```javascript
// Minimal Express endpoint to create a CAPA
const express = require('express');
const app = express();
app.use(express.json());
const caps = [];
app.post('/caps', (req, res) => {
  const c = {
    id: `CAPA-${caps.length+1}`,
    title: req.body.title,
    rootCause: req.body.rootCause,
    containment: req.body.containment,
    correctiveAction: req.body.correctiveAction,
    preventiveAction: req.body.preventiveAction,
    evidence: req.body.evidence || [],
    status: 'discovered',
    owner: req.body.owner || 'unassigned',
    createdAt: new Date(),
    updatedAt: new Date()
  };
  caps.push(c);
  res.status(201).json(c);
});
app.listen(3000, () => console.log('CAPA API listening'));
```

